window.docContents[123].resolve({"/rules/PL1006/#PL1006-limitations":{"contents":"The helper exception is conservative: elaborators defined in the audited module, run_tac or by_elab in the recursion's proofs make the checker reject a definition Lean accepts.\n\nEditor feedback may be pending until the project command completes the fresh-frontend check.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1006: Unsafe and partial declarations require exact helper authentication","header":"Limitations and unsupported cases","id":"/rules/PL1006/#PL1006-limitations"},"/rules/PL2005/#PL2005-limitations":{"contents":"This page's example is a diagnostic demonstration: the violating run is INCOMPLETE by design and is not accepted negative evidence. Its corrected counterpart passed a completed positive check.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2005: Required admission and source evidence must be complete","header":"Limitations and unsupported cases","id":"/rules/PL2005/#PL2005-limitations"},"/rules/PL4003/#PL4003-limitations":{"contents":"Plumb policy rejections of documentation examples can follow successful elaboration; this rule concerns compiler rejection patterns of lean-fail fences.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4003: Negative examples require completed intended rejection","header":"Limitations and unsupported cases","id":"/rules/PL4003/#PL4003-limitations"},"/rules/PL5002/#PL5002-limitations":{"contents":"Lean's broader linter.missingDocs checks all public declarations; this rule deliberately covers only registered material evidence.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL5002: Registered public material declarations require docstrings","header":"Limitations and unsupported cases","id":"/rules/PL5002/#PL5002-limitations"}});